public class ImmutableLoanReceipt{static class LoanReceipt{private final String memberId;private final String[] bookIds;LoanReceipt(String m,String[] b){memberId=m;bookIds=b.clone();}String[] getBookIds(){return bookIds.clone();}LoanReceipt withCorrectedBookId(int i,String id){String[] b=bookIds.clone();b[i]=id;return new LoanReceipt(memberId,b);}}static class ReferenceOnlyLoanReceipt extends LoanReceipt{ReferenceOnlyLoanReceipt(String m,String[] b,String r){super(m,b);}}static String processNightlyCirculation(LoanReceipt[] a){int p=0,n=0,r=0;for(LoanReceipt x:a){if(x==null)n++;else{p++;if(x instanceof ReferenceOnlyLoanReceipt)r++;}}return p+" processed | "+n+" null skipped | "+r+" reference-only | "+(p-r)+" regular";}}